back:
Check the lengths, then **count each value** in the first array with a `Map` and subtract counts while walking the second array. If a count is ever missing or drops below zero, the arrays differ.

```js
const equalsIgnoreOrder = (a, b) => {
  if (a.length !== b.length) return false;
  const counts = new Map();
  for (const v of a) counts.set(v, (counts.get(v) ?? 0) + 1);
  for (const v of b) {
    const n = counts.get(v);
    if (!n) return false;
    counts.set(v, n - 1);
  }
  return true;
};

equalsIgnoreOrder([1, 2, 2], [2, 1, 2]); // true
equalsIgnoreOrder([1, 1, 2], [1, 2, 2]); // false
```

Why not sort both and compare? Sorting works but costs O(n log n) and mutates unless you copy. Values are compared like `===` (with `NaN` treated as equal), so objects only match by reference.

