`split(',')` also splits on commas **inside quoted fields** (`"Smith, Ana"`) and leaves the quote characters in. A parser walks the line character by character, tracking whether it is inside quotes: commas only end a field outside quotes, and `""` inside quotes means one literal `"`.

```js
const parseRow = (row, d = ',') => {
  const values = [];
  let cur = '', inQuotes = false;
  for (let i = 0; i < row.length; i++) {
    const ch = row[i];
    if (inQuotes) {
      if (ch === '"' && row[i + 1] === '"') { cur += '"'; i++; }
      else if (ch === '"') inQuotes = false;
      else cur += ch;
    } else if (ch === '"') inQuotes = true;
    else if (ch === d) { values.push(cur); cur = ''; }
    else cur += ch;
  }
  values.push(cur);
  return values;
};

