```js
const superset = (a, b) => {
  const sA = new Set(a), sB = new Set(b);
  return [...sB].every(v => sA.has(v));
};
const subset = (a, b) => superset(b, a);

superset([1, 2, 3, 4], [1, 2, 2]); // true
superset([1, 2, 3, 4], [1, 3, 5]); // false

// e.g. does the user have every required permission?
const granted = new Set(['read', 'write', 'admin']);
granted.isSupersetOf(new Set(['read', 'write'])); // true
```

