class Factory {
  static factoryMap = new Map();

  static prepare(factory, model, base = {}, traits = {}) {
    if (!Factory.factoryMap.has(factory.name)) {
      Factory.factoryMap.set(factory.name, { model, base, traits });
    }
  }
}

