  static factoryMap = new Map();

  static prepare(factory, model, base = {}, traits = {}) {
    const factoryName = factory.name;

    // Store the factory in the factory map
    if (!Factory.factoryMap[factoryName])
      Factory.factoryMap.set(factoryName, {
        model,
        base,
        traits,
      });
  }
}
```

