  Object.values(obj).forEach(v => {
    if (v !== null && typeof v === 'object') deepFreeze(v);
  });
  return Object.freeze(obj);
};

const val = deepFreeze([1, [2, 3]]);
val[0] = 3;    // TypeError: Cannot assign to read only property '0'
val[1][0] = 4; // TypeError (nested array was frozen too)
```

The thrown error is useful: it points straight at the line that tried to mutate shared state, instead of leaving a silent bug.

