Check `process.argv.includes(...)` for each flag. A small helper can add the `--` prefix when you leave it off. For anything more than presence checks, use Node's built-in `util.parseArgs`.

```js
import { parseArgs } from 'node:util';

const hasFlags = (...flags) =>
  flags.every(flag =>
    process.argv.includes(/^-{1,2}/.test(flag) ? flag : '--' + flag)
  );

// $ node my-script.js -s --test
hasFlags('-s');         // true
hasFlags('test', '-s'); // true ('test' becomes '--test')
hasFlags('special');    // false

const { values } = parseArgs({
  options: {
    silent: { type: 'boolean', short: 's' },
    test: { type: 'boolean' },
  },
});
values; // { silent: true, test: true } (unknown flags throw)
```

`includes` does exact matching, so `--name=John` is only found if you search for the whole string.

