import { access, mkdir } from 'fs/promises';

const createDirIfNotExists = dir =>
  access(dir)
    .then(() => undefined)
    .catch(() => mkdir(dir));

createDirIfNotExists('test');
// Asynchronously creates the directory 'test', if it doesn't exist
```

