  if (arity > args.length) throw new RangeError('Arguments too few!');
  return args.slice(0, arity).reduce((f, arg) => f(arg), fn);
};

const add = x => y => z => x + y + z;
uncurry(add, 3)(1, 2, 3); // 6
```

This mostly comes up in functional-programming libraries. In app code you'd usually just write `add(1)(2)(3)` or define a normal three-argument function.

