readFileSync('test.txt').toString('UTF8');
// 'line1\nline2\nline3\n'
readFile('test.txt', 'UTF8');
// 'line1\nline2\nline3\n'

readFile('test.txt').then(data => data.toString());
// Promise {'line1\nline2\nline3\n'}
readFile('test.txt', 'UTF8');
// Promise {'line1\nline2\nline3\n'}
```

