class Currency {
  static get(code) {
    const currency = getCurrencyFromCode(code);
    if (!currency) throw new RangeError(`Invalid currency ISO code "${code}"`);
    return currency;
  }
  static wrap(currency) {
    if (typeof currency === 'object' && getCurrencyFromCode(currency.code) === currency)
      return currency;
    return Currency.get(currency);
  }
}

Currency.get('usd') === Currency.get('USD'); // true (same object)
Currency.wrap(Currency.get('usd')) === Currency.get('usd'); // true
Currency.get('xyz'); // RangeError: Invalid currency ISO code "xyz"
```

Uppercasing makes lookups case-insensitive. Throwing on an unknown code surfaces a typo straight away instead of producing `undefined` money.

