```js
const ordinalsEnUS = { one: 'st', two: 'nd', few: 'rd', other: 'th' };

const toOrdinalSuffix = (num, locale = 'en-US', ordinals = ordinalsEnUS) => {
  const pluralRules = new Intl.PluralRules(locale, { type: 'ordinal' });
  return `${num}${ordinals[pluralRules.select(num)]}`;
};

toOrdinalSuffix(1);   // '1st'
toOrdinalSuffix(11);  // '11th'
toOrdinalSuffix(22);  // '22nd'
toOrdinalSuffix(123); // '123rd'
```

Without `type: 'ordinal'` you get cardinal rules (`1` → `'one'`, everything else `'other'`), so `2` would become `'2th'`. Other languages have different categories, so the suffix map is per locale.

