Walk up with `parentElement`, add each ancestor to the front of an array, and stop as soon as one `matches(selector)`. If none matches, return an empty array.

```js
const getParentsUntil = (el, selector) => {
  const parents = [];
  for (let node = el.parentElement; node; node = node.parentElement) {
    parents.unshift(node);
    if (node.matches(selector)) return parents;
  }
  return []; // no ancestor matched
};

