// server-config.js
const host = 'localhost';
const port = 8000;

export { host, port };
export { port as defaultPort }; // renaming is allowed

// export { port: 8000 };  → SyntaxError: Unexpected token ':'
```

Importers use braces as for any named export: `import { host, port } from './server-config.js';`. Many people like export lists because the module's public API is visible in one place at the bottom of the file.

