```js
// h: 0-360, s and b: 0-100 → [r, g, b] in 0-255
const hsbToRgb = (h, s, b) => {
  s /= 100;
  b /= 100;
  const k = n => (n + h / 60) % 6;
  const f = n => b * (1 - s * Math.max(0, Math.min(k(n), 4 - k(n), 1)));
  return [255 * f(5), 255 * f(3), 255 * f(1)];
};

hsbToRgb(18, 81, 99); // [252.45, 109.31084999999996, 47.965499999999984]
hsbToRgb(18, 81, 99).map(Math.round); // [252, 109, 48]
```

To go from hex to HSB (or HSL), convert hex → RGB first, then RGB → HSB. The same applies in reverse.

