  r /= 255;
  g /= 255;
  b /= 255;
  const v = Math.max(r, g, b);
  const n = v - Math.min(r, g, b);
  const h =
    n === 0 ? 0 : v === r ? (g - b) / n : v === g ? 2 + (b - r) / n : 4 + (r - g) / n;
  return [60 * (h < 0 ? h + 6 : h), v && (n / v) * 100, v * 100];
};

rgbToHsb(252, 111, 48).map(Math.round); // [19, 81, 99]
```

`v && (n / v) * 100` returns 0 for black instead of dividing by zero. Hex → HSB is two steps: hex → RGB, then this function.

