Keep all field values in one state object and give each input a `name`. The shared handler copies the object and overwrites the key matching `e.target.name`. Using `setValues(prev => ...)` means it always builds on the latest values, not on a copy captured by an older render.

```jsx
function useForm(initialValues) {
  const [values, setValues] = useState(initialValues);
  const handleChange = e => {
    const { name, value } = e.target;
    setValues(prev => ({ ...prev, [name]: value }));
  };
  return [values, handleChange];
}

function LoginForm() {
  const [values, handleChange] = useForm({ email: '', password: '' });
  return (
    <form onSubmit={e => { e.preventDefault(); console.log(values); }}>
      <input type="email" name="email" value={values.email} onChange={handleChange} />
      <input type="password" name="password" value={values.password} onChange={handleChange} />
      <button type="submit">Log in</button>
    </form>
  );
}
```

Pitfall: `setValues({ ...values, [name]: value })` can drop an update if two changes happen before a re-render. Also pass `value={...}` so the inputs are controlled; without it the state and the DOM can drift apart (e.g. after a reset).

